// C421: Source consumer only. All mechanics/documents/identities are issued by Native RPCs.
export const VERSION='rapid-unified-import-ui/1';
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i,SHA=/^[0-9a-f]{64}$/;
const clone=x=>structuredClone(x),exact=(x,k)=>x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).sort().join()===k.slice().sort().join();
const fail=m=>{throw Error(m);},node=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n;};
const validReceipt=x=>exact(x,['schema_version','request_key','draft_id','control_version','rapid_draft_id','document_sha256','publication_ready'])&&x.schema_version==='rapid-unified-quest-import/1'&&UUID.test(x.request_key)&&UUID.test(x.draft_id)&&UUID.test(x.rapid_draft_id)&&x.control_version===2&&SHA.test(x.document_sha256)&&x.publication_ready===false;
const stamp=s=>JSON.stringify([s.draftId,s.controlVersion,s.previewSeal,s.dirty,s.compiled]);
export function createRapidQuestImport({client,identity,readRapid,isCurrent,setBusy=()=>{},onDraft=()=>{}}={}){
 if(!client?.rpc||typeof identity!=='function'||typeof readRapid!=='function'||typeof isCurrent!=='function')fail('Consumer import non disponibile.');
 const actor=identity();let catalog=null,selection=null,proposal=null,pending=null,receipt=null,currentDraft=null,message='',busy=false,slot=null,disposed=false,notFoundCount=0,knownRapid=null;
 const current=()=>!disposed&&isCurrent()&&identity()===actor,storageKey=id=>'tus:rapid-unified-import:'+actor+':'+id;
 function sealed(){const s=readRapid();if(!UUID.test(s?.draftId||'')||!Number.isSafeInteger(s.controlVersion)||s.controlVersion<1||!SHA.test(s.previewSeal||'')||s.dirty||s.preview?.draft_version!==s.controlVersion||s.preview?.errors?.length)fail('Salva la bozza e completa l’anteprima originale prima dell’importazione.');return s;}
 function savePending(value){try{localStorage.setItem(storageKey(value.p_rapid),JSON.stringify(value));}catch{fail('Archivio locale non disponibile: nessun import avviato.');}}
 function restore(){const id=readRapid()?.draftId;if(!UUID.test(id||'')||knownRapid===id)return;knownRapid=id;catalog=selection=proposal=receipt=currentDraft=null;pending=null;notFoundCount=0;try{const x=JSON.parse(localStorage.getItem(storageKey(id))||'null');if(x&&exact(x,['p_request','p_rapid','p_expected_version','p_preview_seal','p_catalog_version','p_selection'])&&UUID.test(x.p_request)&&x.p_rapid===id&&Number.isSafeInteger(x.p_expected_version)&&SHA.test(x.p_preview_seal)&&typeof x.p_catalog_version==='string'&&exact(x.p_selection,['schema_version','phases','terminal_step_key','outcome_capability_key']))pending=x;}catch{message='Richiesta locale non leggibile: usa il recupero della ricevuta per questa bozza.';}}
 async function rpc(name,args){if(!current())fail('Accesso editor cambiato.');const a=await client.auth.getUser();if(a.error||a.data?.user?.id!==actor||!current())fail('Sessione Staff non verificata.');const r=await client.rpc(name,args);const b=await client.auth.getUser();if(b.error||b.data?.user?.id!==actor||!current())fail('Accesso editor cambiato durante la richiesta. Recupera con l’accesso originale.');if(r.error)throw r.error;return r.data;}
 async function run(fn){if(busy)return;busy=true;setBusy(true);render();try{await fn();}catch(e){message=e?.message||'Operazione non confermata: conserva la richiesta e recupera la ricevuta.';}finally{busy=false;setBusy(false);render();}}
 function checkCatalog(v,s){if(!exact(v,['schema_version','rapid_draft_id','rapid_control_version','rapid_document_sha256','catalog_version','catalog_sha256','choices','d100_policy_choices'])||v.schema_version!=='rapid-unified-quest-native-catalog/1'||v.rapid_draft_id!==s.draftId||v.rapid_control_version!==s.controlVersion||!SHA.test(v.rapid_document_sha256)||!SHA.test(v.catalog_sha256)||typeof v.catalog_version!=='string'||!Array.isArray(v.choices)||!Array.isArray(v.d100_policy_choices))fail('Catalogo import non compatibile.');for(const x of v.choices)if(!exact(x,['capability_key','decision_key','terminal_route','native_combat_outcome','step_kind'])||typeof x.capability_key!=='string'||typeof x.decision_key!=='string'||typeof x.terminal_route!=='boolean'||!(x.native_combat_outcome===null||typeof x.native_combat_outcome==='string')||typeof x.step_kind!=='string')fail('Scelta Native non compatibile.');for(const x of v.d100_policy_choices)if(!exact(x,['policy_mission_id','policy_step_key'])||!UUID.test(x.policy_mission_id)||typeof x.policy_step_key!=='string')fail('Policy d100 non compatibile.');}
 async function load(){return run(async()=>{restore();if(pending||receipt)fail('Prima recupera la richiesta precedente.');const s=sealed(),key=stamp(s),v=await rpc('mission_factory_rapid_quest_catalog_v1',{p_rapid:s.draftId,p_expected_version:s.controlVersion});if(stamp(readRapid())!==key)fail('La bozza è cambiata: rileggi il catalogo.');checkCatalog(v,s);catalog=v;proposal=null;selection={schema_version:'rapid-quest-native-selection/1',phases:s.compiled.phases.map(p=>({step_key:p.step_key,capability_key:'',decisions:(p.transitions||[]).map(t=>({transition_key:t.transition_key,decision_key:'',terminal_outcome:null})),d100_policy:null})),terminal_step_key:'',outcome_capability_key:'terminal.result'};message='Scegli le corrispondenze del catalogo per ogni fase e passaggio.';});}
 function checkSelection(s){if(!catalog||!selection||catalog.rapid_draft_id!==s.draftId||catalog.rapid_control_version!==s.controlVersion)fail('Rileggi il catalogo della versione corrente.');if(!selection.phases.some(p=>p.step_key===selection.terminal_step_key&&p.capability_key==='terminal.result'))fail('Scegli la fase conclusiva.');for(const p of selection.phases){if(!p.capability_key||p.decisions.some(d=>!d.decision_key)||new Set(p.decisions.map(d=>d.decision_key)).size!==p.decisions.length)fail('Completa le scelte Native senza duplicare le decisioni.');if(p.capability_key==='d100.native'&&!p.d100_policy)fail('Scegli una challenge Native per il d100.');}}
 async function prepare(){return run(async()=>{if(pending||receipt)fail('Prima recupera l’import precedente.');const s=sealed();checkSelection(s);const key=stamp(s),mapped=clone(selection),v=await rpc('mission_factory_rapid_quest_prepare_v1',{p_rapid:s.draftId,p_expected_version:s.controlVersion,p_preview_seal:s.previewSeal,p_catalog_version:catalog.catalog_version,p_selection:mapped});if(stamp(readRapid())!==key||JSON.stringify(selection)!==JSON.stringify(mapped))fail('Le scelte sono cambiate: rigenera l’anteprima import.');if(!exact(v,['schema_version','rapid_draft_id','rapid_control_version','rapid_document_sha256','rapid_source_sha256','rapid_preview_seal','catalog_version','catalog_sha256','document','document_sha256','editorial_suggestions','direction_compatibility','publication_ready'])||v.schema_version!=='rapid-unified-quest-proposal/1'||v.rapid_draft_id!==s.draftId||v.rapid_control_version!==s.controlVersion||v.rapid_preview_seal!==s.previewSeal||v.catalog_version!==catalog.catalog_version||v.catalog_sha256!==catalog.catalog_sha256||['rapid_document_sha256','rapid_source_sha256','document_sha256'].some(k=>!SHA.test(v[k]||''))||v.document?.schema_version!=='mission-factory-draft/2'||v.document?.content_kind!=='quest_ai'||!exact(v.direction_compatibility,['ai','human'])||v.direction_compatibility.ai!=='draft_only'||v.direction_compatibility.human!=='consumer_contract_required'||v.publication_ready!==false)fail('Anteprima import non compatibile.');proposal={value:v,stamp:key,selection:JSON.stringify(mapped)};message='Anteprima import pronta. Conferma la creazione della bozza; pubblicazione separata nell’Editor.';});}
 async function recoverInternal(){restore();const s=readRapid(),id=s?.draftId;if(!UUID.test(id||''))fail('Bozza Rapid non disponibile.');let request=pending?.p_request??null,v;try{v=await rpc('mission_factory_rapid_quest_import_receipt_v1',{p_rapid:id,p_request:request});}catch(e){if(!String(e?.message||'').includes('C413_IMPORT_REQUEST_CONFLICT'))throw e;request=null;v=await rpc('mission_factory_rapid_quest_import_receipt_v1',{p_rapid:id,p_request:null});}if(readRapid()?.draftId!==id)fail('La bozza selezionata è cambiata: la ricevuta precedente resta recuperabile dal suo ID.');if(!exact(v,['schema_version','status','request_key','rapid_draft_id','receipt','current_draft'])||v.schema_version!=='rapid-unified-import-seal/1'||v.rapid_draft_id!==id||!['committed','not_found'].includes(v.status))fail('Ricevuta import non compatibile.');if(v.status==='not_found'){if(v.receipt!==null||v.current_draft!==null||v.request_key!==request)fail('Ricevuta assente non compatibile.');notFoundCount++;message='Nessuna ricevuta trovata. Nessun nuovo import automatico.';return false;}if(!validReceipt(v.receipt)||v.receipt.rapid_draft_id!==id||v.request_key!==v.receipt.request_key||(request&&v.request_key!==request)||!exact(v.current_draft,['draft_id','control_version','state','document_sha256'])||v.current_draft.draft_id!==v.receipt.draft_id||!Number.isSafeInteger(v.current_draft.control_version)||v.current_draft.control_version<2||!['draft','previewed','published','suspended'].includes(v.current_draft.state)||!SHA.test(v.current_draft.document_sha256))fail('Ricevuta committata non compatibile.');receipt=clone(v.receipt);currentDraft=clone(v.current_draft);notFoundCount=0;message='Import già concluso. Apri la bozza unificata corrente; il Rapid originale resta nello storico.';return true;}
 async function recover(){return run(recoverInternal);}
 async function commit(){return run(async()=>{const s=sealed();if(!proposal||proposal.stamp!==stamp(s)||proposal.selection!==JSON.stringify(selection))fail('Rigenera l’anteprima import corrente.');if(pending||receipt)fail('Recupera la richiesta precedente prima di confermare.');pending={p_request:crypto.randomUUID(),p_rapid:s.draftId,p_expected_version:s.controlVersion,p_preview_seal:s.previewSeal,p_catalog_version:catalog.catalog_version,p_selection:clone(selection)};savePending(pending);const submitted=clone(pending),expectedHash=proposal.value.document_sha256,v=await rpc('mission_factory_rapid_quest_commit_v1',submitted);if(!validReceipt(v)||v.request_key!==submitted.p_request||v.rapid_draft_id!==submitted.p_rapid||v.document_sha256!==expectedHash)fail('Import non confermato: recupera la stessa ricevuta.');if(readRapid()?.draftId!==submitted.p_rapid){message='Import concluso per la bozza precedente: recuperala dal suo ID senza ripetere l’import.';return;}receipt=clone(v);await recoverInternal();});}
 async function open(){return run(async()=>{if(!await recoverInternal())return;const v=clone(currentDraft),r=clone(receipt);await onDraft({schema_version:VERSION,receipt:r,current_draft:v});});}
 function retire(){if(notFoundCount<2||receipt||!pending||busy)return;try{localStorage.removeItem(storageKey(pending.p_rapid));}catch{message='Richiesta conservata: archivio locale non disponibile.';return;}pending=null;proposal=null;notFoundCount=0;message='Richiesta precedente archiviata dopo due letture senza ricevuta. Rigenera l’anteprima prima di una nuova conferma.';render();}
 function select(items,value,change){const s=node('select');for(const [k,label]of [['','Scegli…'],...items]){const o=node('option',label);o.value=k;s.append(o);}s.value=value||'';s.disabled=busy||!!pending||!!receipt;s.onchange=()=>{change(s.value);proposal=null;render();};return s;}
 function button(text,fn,off=false){const n=node('button',text);n.type='button';n.disabled=busy||off;n.onclick=()=>{void fn();};return n;}
 function render(){if(!slot||!current())return;restore();slot.replaceChildren();slot.className='mr-card';slot.append(node('h3','Porta nell’Editor unificato'),node('p',message||'Completa l’anteprima Rapid e scegli le corrispondenze Native. Nessuna pubblicazione automatica.'));
 slot.append(button('Leggi catalogo import',load,!!pending||!!receipt),button('Recupera import già concluso',recover,!UUID.test(readRapid()?.draftId||'')));
 if(catalog&&selection){for(const p of selection.phases){const original=readRapid().compiled.phases.find(x=>x.step_key===p.step_key),box=node('div');box.className='mr-subcard';box.append(node('h4',original?.title||p.step_key));const caps=[...new Set(catalog.choices.map(x=>x.capability_key))].filter(k=>original?.kind==='combat'?k==='combat.encounter':k==='narrative.scene'||k==='terminal.result'||(k==='d100.native'&&original?.kind==='exploration'));box.append(select(caps.map(k=>[k,k]),p.capability_key,k=>{p.capability_key=k;p.decisions.forEach(d=>{d.decision_key='';d.terminal_outcome=null;});p.d100_policy=null;}));for(const d of p.decisions){const tr=original?.transitions?.find(t=>t.transition_key===d.transition_key),choices=catalog.choices.filter(x=>x.capability_key===p.capability_key&&x.terminal_route===(tr?.to_step_key==null));box.append(node('p',d.transition_key+' → '+(tr?.to_step_key||'Conclusione')),select(choices.map(x=>[x.decision_key,x.decision_key]),d.decision_key,k=>{d.decision_key=k;d.terminal_outcome=k==='terminal.success'?'success':k==='terminal.failure'?'failure':null;}));}if(p.capability_key==='d100.native')box.append(select(catalog.d100_policy_choices.map((x,i)=>[String(i),x.policy_step_key]),p.d100_policy?String(catalog.d100_policy_choices.findIndex(x=>JSON.stringify(x)===JSON.stringify(p.d100_policy))):'',i=>{p.d100_policy=i===''?null:clone(catalog.d100_policy_choices[Number(i)]);}));slot.append(box);}slot.append(node('p','Fase conclusiva'),select(selection.phases.map(p=>[p.step_key,p.step_key]),selection.terminal_step_key,k=>{selection.terminal_step_key=k;}),button('Anteprima import',prepare,!!pending||!!receipt));}
 if(proposal){const text=node('pre',JSON.stringify(proposal.value.document,null,2));slot.append(text,button('Conferma creazione bozza',commit,!!pending||!!receipt));}if(pending&&!receipt)slot.append(node('p','Richiesta conservata: '+pending.p_request),button('Archivia richiesta senza ricevuta',retire,notFoundCount<2));if(receipt)slot.append(button('Apri bozza nell’Editor',open));}
 return {render(target){slot=target;render();},recover,hasCommitted:()=>!!receipt,openCommitted:open,dispose(){disposed=true;slot=null;}};
}
